import { execFileSync } from "node:child_process";
import { homedir } from "node:os";
import { basename, relative } from "node:path";
import process from "node:process";
import type {
  ExtensionAPI,
  ExtensionContext,
  ReadonlyFooterDataProvider,
} from "@earendil-works/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

type ThinkingLevel = ReturnType<ExtensionAPI["getThinkingLevel"]>;

interface RuntimeState {
  thinkingLevel: ThinkingLevel;
  requestRender?: () => void;
}

interface TokenTotals {
  input: number;
  output: number;
  cost: number;
}

interface Chip {
  label: string;
  value: string;
  accent: string;
  priority: 1 | 2 | 3;
  labelFg?: string;
  valueFg?: string;
  valueBg?: string;
  boldValue?: boolean;
}

interface GitSnapshot {
  branch?: string;
  worktreeRoot?: string;
  status?: string;
  dirty: boolean;
  expiresAt: number;
}

interface GitStatusCounts {
  conflicted: number;
  modified: number;
  untracked: number;
  staged: number;
  renamed: number;
  deleted: number;
  ahead: number;
  behind: number;
}

const FOOTER_KEY = "pi-status";
const CODEX_USAGE_STATUS_KEY = "codex-usage";
const GIT_CACHE_TTL_MS = 2_000;
const GIT_COMMAND_TIMEOUT_MS = 350;
const gitCache = new Map<string, GitSnapshot>();

const COLOR = {
  ink: "#f8fafc",
  soft: "#cbd5e1",
  dim: "#94a3b8",
  black: "#020617",
  panel: "#111827",
  panelLift: "#1f2937",
  panelSoft: "#334155",
  separator: "#1e293b",
  path: "#38bdf8",
  model: "#60a5fa",
  contextTransparent: "#1f2937",
  contextLightGreen: "#86efac",
  contextGreen: "#22c55e",
  contextYellow: "#eab308",
  contextOrange: "#f97316",
  contextRed: "#ef4444",
  contextWarn: "#f97316",
  contextFull: "#ef4444",
  thinkOff: "#64748b",
  thinkMinimal: "#22d3ee",
  thinkLow: "#38bdf8",
  thinkMedium: "#a78bfa",
  thinkHigh: "#f59e0b",
  thinkXhigh: "#f43f5e",
  codex: "#06b6d4",
  git: "#22c55e",
  gitDirty: "#f59e0b",
  token: "#64748b",
  cost: "#15803d",
} as const;

export default function piStatus(pi: ExtensionAPI): void {
  let enabled = process.env.PI_STATUS !== "0";
  const runtime: RuntimeState = {
    thinkingLevel: "off",
  };

  const refresh = () => runtime.requestRender?.();

  const installFooter = (ctx: ExtensionContext) => {
    if (ctx.mode !== "tui") return;

    ctx.ui.setStatus(FOOTER_KEY, undefined);

    if (!enabled) {
      ctx.ui.setFooter(undefined);
      runtime.requestRender = undefined;
      return;
    }

    ctx.ui.setFooter((tui, _theme, footerData) => {
      runtime.requestRender = () => tui.requestRender();
      const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());
      const clock = setInterval(() => tui.requestRender(), 60_000);

      return {
        dispose() {
          unsubscribeBranch();
          clearInterval(clock);
        },
        invalidate() {},
        render(width: number): string[] {
          if (width <= 0) return [""];
          return [
            renderPrimaryLine(width, ctx, footerData, runtime),
            renderSeparatorLine(width),
            renderUsageLine(width, ctx, footerData),
          ];
        },
      };
    });
  };

  pi.registerCommand("pi-status", {
    description: "Toggle the high-contrast Pi status footer. Usage: /pi-status [on|off|toggle]",
    handler: async (args, ctx) => {
      const action = args.trim().toLowerCase();
      if (action === "on") enabled = true;
      else if (action === "off") enabled = false;
      else enabled = !enabled;

      installFooter(ctx);
      ctx.ui.notify(`High-contrast status footer ${enabled ? "enabled" : "disabled"}`, "info");
    },
  });

  pi.on("session_start", (_event, ctx) => {
    runtime.thinkingLevel = pi.getThinkingLevel();
    installFooter(ctx);
  });

  pi.on("session_tree", (_event, ctx) => {
    installFooter(ctx);
    refresh();
  });

  pi.on("session_shutdown", (_event, ctx) => {
    if (ctx.mode === "tui") ctx.ui.setFooter(undefined);
    ctx.ui.setStatus(FOOTER_KEY, undefined);
    runtime.requestRender = undefined;
  });

  pi.on("model_select", () => refresh());
  pi.on("agent_end", () => refresh());
  pi.on("turn_end", () => refresh());

  pi.on("thinking_level_select", (event) => {
    runtime.thinkingLevel = event.level;
    refresh();
  });
}

function renderPrimaryLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
  runtime: RuntimeState,
): string {
  const context = contextSnapshot(ctx);
  const right: Chip[] = [
    chip("MODEL", modelName(ctx), COLOR.model, 1, { valueBg: COLOR.panelLift, boldValue: true }),
    chip("THINK", formatThinking(runtime.thinkingLevel), thinkingColor(runtime.thinkingLevel), 2, {
      valueBg: COLOR.panelLift,
    }),
    chip("CTX", context.label, context.color, 1, {
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  ];

  return fitLeftRight(width, right, (available) => renderPathCluster(available, ctx, footerData));
}

function renderUsageLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
): string {
  const totals = getTokenTotals(ctx);
  const right: Chip[] = [
    chip("↑", formatCount(totals.input), COLOR.token, 1),
    chip("↓", formatCount(totals.output), COLOR.token, 1),
    chip("$", formatCost(totals.cost), COLOR.cost, 2, { boldValue: true }),
  ];

  return fitLeftRight(width, right, (available) => renderCodexStatus(available, footerData));
}

function renderSeparatorLine(width: number): string {
  return ansi("─".repeat(Math.max(0, width)), { fg: COLOR.separator });
}

function fitLeftRight(width: number, rightChips: Chip[], renderLeft: (available: number) => string): string {
  for (let priority = 3; priority >= 1; priority -= 1) {
    const right = renderChips(rightChips.filter((item) => item.priority <= priority));
    const rightWidth = visibleWidth(right);
    const gap = rightWidth > 0 ? 1 : 0;
    const availableLeft = Math.max(0, width - rightWidth - gap);
    const left = renderLeft(availableLeft);
    const leftWidth = visibleWidth(left);

    if (leftWidth + rightWidth + gap <= width) {
      const padding = " ".repeat(Math.max(gap, width - leftWidth - rightWidth));
      return truncateToWidth(`${left}${padding}${right}`, width, "");
    }
  }

  return truncateToWidth(renderLeft(width), width, "");
}

function renderPathCluster(maxWidth: number, ctx: ExtensionContext, footerData: ReadonlyFooterDataProvider): string {
  if (maxWidth <= 0) return "";

  const git = getGitSnapshot(ctx.cwd, footerData.getGitBranch());
  const branch = git.branch ?? footerData.getGitBranch();
  const fullPath = formatWorkingPath(ctx.cwd, git.worktreeRoot);

  for (const attempt of [
    { branchWidth: 28, includeStatus: true },
    { branchWidth: 18, includeStatus: true },
    { branchWidth: 12, includeStatus: true },
    { branchWidth: 18, includeStatus: false },
    { branchWidth: 0, includeStatus: true },
    { branchWidth: 0, includeStatus: false },
  ]) {
    const branchChip = attempt.branchWidth > 0 && branch ? renderBranchChip(branch, attempt.branchWidth) : "";
    const statusChip = attempt.includeStatus ? renderGitStatusChip(git) : "";
    const fixed = [branchChip, statusChip].filter(Boolean).join(" ");
    const fixedWidth = visibleWidth(fixed);
    const gap = fixedWidth > 0 ? 1 : 0;
    const pathMaxWidth = Math.max(0, maxWidth - fixedWidth - gap);
    const pathChip = renderFittedPathChip(fullPath, pathMaxWidth);
    const cluster = [pathChip, fixed].filter(Boolean).join(" ");

    if (visibleWidth(cluster) <= maxWidth) return cluster;
  }

  return truncateToWidth(renderFittedPathChip(fullPath, maxWidth), maxWidth, "");
}

