function renderCodexStatus(maxWidth: number, footerData: ReadonlyFooterDataProvider): string {
  if (maxWidth <= 0) return "";

  const raw = footerData.getExtensionStatuses().get(CODEX_USAGE_STATUS_KEY);
  const value = formatCodexValue(raw);
  const accent = codexAccent(raw);
  const full = renderChip(
    chip("CODEX", value, accent, 1, {
      labelFg: accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink,
      valueBg: COLOR.panelLift,
      boldValue: Boolean(raw),
    }),
  );
  if (visibleWidth(full) <= maxWidth) return full;

  const emptyWidth = visibleWidth(
    renderChip(
      chip("CODEX", "", accent, 1, {
        labelFg: accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink,
        valueBg: COLOR.panelLift,
      }),
    ),
  );
  const valueWidth = Math.max(1, maxWidth - emptyWidth);
  return truncateToWidth(
    renderChip(
      chip("CODEX", truncateToWidth(value, valueWidth, "…"), accent, 1, {
        labelFg: accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink,
        valueBg: COLOR.panelLift,
        boldValue: Boolean(raw),
      }),
    ),
    maxWidth,
    "",
  );
}

function chip(
  label: string,
  value: string,
  accent: string,
  priority: 1 | 2 | 3,
  options: Partial<Pick<Chip, "labelFg" | "valueFg" | "valueBg" | "boldValue">> = {},
): Chip {
  return {
    label,
    value,
    accent,
    priority,
    labelFg: options.labelFg,
    valueFg: options.valueFg,
    valueBg: options.valueBg,
    boldValue: options.boldValue,
  };
}

function renderChips(chips: Chip[]): string {
  return chips.map(renderChip).join(" ");
}

function renderChip(item: Chip): string {
  const labelFg = item.labelFg ?? readableTextOn(item.accent);
  const valueFg = item.valueFg ?? item.accent;
  const valueBg = item.valueBg ?? COLOR.panel;

  return [
    ansi("", { fg: item.accent }),
    ansi(` ${item.label} `, { fg: labelFg, bg: item.accent, bold: true }),
    ansi("", { fg: item.accent, bg: valueBg }),
    ansi(` ${item.value} `, { fg: valueFg, bg: valueBg, bold: item.boldValue }),
    ansi("", { fg: valueBg }),
  ].join("");
}

function contextSnapshot(ctx: ExtensionContext): { label: string; color: string } {
  const usage = ctx.getContextUsage();
  const percent = typeof usage?.percent === "number" ? usage.percent : undefined;
  if (percent === undefined) return { label: "?", color: COLOR.contextTransparent };

  const clamped = Math.max(0, Math.min(100, percent));
  return { label: `${clamped.toFixed(0)}%`, color: contextColor(clamped) };
}

function contextColor(percent: number): string {
  if (percent < 10) return COLOR.contextTransparent;
  if (percent < 20) return COLOR.contextLightGreen;
  if (percent < 30) return COLOR.contextGreen;
  if (percent < 40) return COLOR.contextYellow;
  if (percent < 50) return COLOR.contextOrange;
  return COLOR.contextRed;
}

function codexAccent(raw: string | undefined): string {
  const normalized = stripAnsi(raw ?? "").toLowerCase();
  if (!raw) return COLOR.panelSoft;
  if (/error|fail|unavailable|missing/.test(normalized)) return COLOR.contextFull;
  if (/checking|pending|loading/.test(normalized)) return COLOR.contextWarn;
  return COLOR.codex;
}

function formatCodexValue(raw: string | undefined): string {
  if (!raw) return "usage —";

  const value = simplifyStatusText(raw)
    .replace(/^📊\s*/u, "")
    .replace(/^codex\b\s*/iu, "")
    .replace(/\s+(5h|wk)\b/giu, " $1")
    .replace(/\s+/g, " ")
    .trim();

  return value || "usage —";
}

function modelName(ctx: ExtensionContext): string {
  const model = ctx.model as { id?: string; name?: string } | undefined;
  return shortenModel(model?.id ?? model?.name ?? "no model");
}

function shortenModel(model: string): string {
  return shorten(
    model
      .replace(/^claude-/, "")
      .replace(/^gpt-/, "gpt ")
      .replace(/-20\d{6}$/, "")
      .replace(/-latest$/, "")
      .replace(/-(instruct|preview|thinking)$/i, ""),
    28,
  );
}

function formatThinking(level: ThinkingLevel): string {
  if (level === "xhigh") return "x-high";
  return level;
}

function thinkingColor(level: ThinkingLevel): string {
  switch (level) {
    case "off":
      return COLOR.thinkOff;
    case "minimal":
      return COLOR.thinkMinimal;
    case "low":
      return COLOR.thinkLow;
    case "medium":
      return COLOR.thinkMedium;
    case "high":
      return COLOR.thinkHigh;
    case "xhigh":
      return COLOR.thinkXhigh;
  }
}

function renderPathChip(value: string): string {
  return renderChip(
    chip("", value, COLOR.path, 1, {
      labelFg: COLOR.black,
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  );
}

function renderFittedPathChip(path: string, maxWidth: number): string {
  if (maxWidth <= 0) return "";

  const fullPathChip = renderPathChip(path);
  if (visibleWidth(fullPathChip) <= maxWidth) return fullPathChip;

  const emptyPathChipWidth = visibleWidth(renderPathChip(""));
  const pathWidth = Math.max(3, maxWidth - emptyPathChipWidth);
  return truncateToWidth(renderPathChip(smartPathTruncate(path, pathWidth)), maxWidth, "");
}

function renderBranchChip(branch: string, maxWidth: number): string {
  return renderChip(chip("", shorten(branch, maxWidth), COLOR.git, 2, { labelFg: COLOR.black }));
}

function renderGitStatusChip(git: GitSnapshot): string {
  if (!git.status) return "";

  const accent = git.dirty ? COLOR.gitDirty : COLOR.git;
  return renderChip(
    chip("≡", git.status, accent, 2, {
      labelFg: COLOR.black,
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  );
}

function formatWorkingPath(cwd: string, worktreeRoot?: string): string {
  if (worktreeRoot) {
    const worktreePath = formatWorktreePath(cwd, worktreeRoot);
    if (worktreePath) return worktreePath;
  }

  const home = homedir();
  if (cwd === home) return "~";
  if (cwd.startsWith(`${home}/`)) return `~/${cwd.slice(home.length + 1)}`;
  return cwd;
}

function formatWorktreePath(cwd: string, worktreeRoot: string): string | undefined {
  const rel = relative(worktreeRoot, cwd);
  if (rel.startsWith("..")) return undefined;

  const rootName = basename(worktreeRoot) || worktreeRoot;
  if (!rel) return rootName;
  return `${rootName}/${rel}`;
}

function smartPathTruncate(path: string, maxWidth: number): string {
  if (visibleWidth(path) <= maxWidth) return path;
  const parts = path.split("/").filter(Boolean);
  if (parts.length >= 2 && maxWidth >= 12) {
    const tail = parts.slice(-2).join("/");
    return truncateToWidth(`…/${tail}`, maxWidth, "…");
  }
  return truncateToWidth(path, maxWidth, "…");
}

function getGitSnapshot(cwd: string, fallbackBranch?: string): GitSnapshot {
  const now = Date.now();
  const cached = gitCache.get(cwd);
  if (cached && cached.expiresAt > now) {
    return fallbackBranch && cached.branch !== fallbackBranch ? { ...cached, branch: fallbackBranch } : cached;
  }

  try {
    const worktreeRoot = execGit(cwd, ["rev-parse", "--show-toplevel"]);
    const statusOutput = execGit(cwd, ["status", "--porcelain=v1", "--branch"]);
    const parsed = parseGitStatus(statusOutput);
    const snapshot: GitSnapshot = {
      branch: fallbackBranch ?? parsed.branch,
      worktreeRoot,
      status: formatGitStatus(parsed.counts),
      dirty: isDirty(parsed.counts),
      expiresAt: now + GIT_CACHE_TTL_MS,
    };
    gitCache.set(cwd, snapshot);
    return snapshot;
  } catch {
    const snapshot: GitSnapshot = {
      branch: fallbackBranch,
      dirty: false,
      expiresAt: now + GIT_CACHE_TTL_MS,
    };
    gitCache.set(cwd, snapshot);
    return snapshot;
  }
}

function execGit(cwd: string, args: string[]): string {
  return execFileSync("git", ["-C", cwd, ...args], {
    encoding: "utf8",
    maxBuffer: 1024 * 1024,
    stdio: ["ignore", "pipe", "ignore"],
    timeout: GIT_COMMAND_TIMEOUT_MS,
  }).trim();
}

function parseGitStatus(output: string): { branch?: string; counts: GitStatusCounts } {
  const counts: GitStatusCounts = {
    conflicted: 0,
    modified: 0,
    untracked: 0,
    staged: 0,
    renamed: 0,
    deleted: 0,
    ahead: 0,
    behind: 0,
  };
  let branch: string | undefined;

  for (const line of output.split(/\r?\n/)) {
    if (!line) continue;

    if (line.startsWith("## ")) {
      branch = parseStatusBranch(line.slice(3));
      counts.ahead += Number(line.match(/ahead (\d+)/)?.[1] ?? 0);
      counts.behind += Number(line.match(/behind (\d+)/)?.[1] ?? 0);
      continue;
    }

    const x = line[0];
    const y = line[1];
    const xy = `${x}${y}`;

    if (xy === "??") {
      counts.untracked += 1;
      continue;
    }
    if (xy === "!!") continue;
    if (["DD", "AU", "UD", "UA", "DU", "AA", "UU"].includes(xy)) {
      counts.conflicted += 1;
      continue;
    }

    if (x === "R" || x === "C") counts.renamed += 1;
    else if (x === "D") counts.deleted += 1;
    else if (x !== " ") counts.staged += 1;

    if (y === "D") counts.deleted += 1;
    else if (y === "M" || y === "T") counts.modified += 1;
  }

  return { branch, counts };
}

function parseStatusBranch(header: string): string | undefined {
  const value = header.replace(/\s+\[[^\]]+\]$/, "").split("...")[0];
  if (!value || value.startsWith("HEAD ")) return undefined;
  return value;
}

function formatGitStatus(counts: GitStatusCounts): string | undefined {
  const parts = [
    formatGitStatusPart("=", counts.conflicted),
    formatGitStatusPart("⇡", counts.ahead),
    formatGitStatusPart("⇣", counts.behind),
    formatGitStatusPart("~", counts.modified),
    formatGitStatusPart("?", counts.untracked),
    formatGitStatusPart("+", counts.staged),
    formatGitStatusPart("»", counts.renamed),
    formatGitStatusPart("-", counts.deleted),
  ].filter((part): part is string => part !== undefined);

  return parts.length > 0 ? parts.join(" ") : undefined;
}

function formatGitStatusPart(symbol: string, count: number): string | undefined {
  return count > 0 ? `${symbol}${count}` : undefined;
}

function isDirty(counts: GitStatusCounts): boolean {
  return counts.conflicted + counts.modified + counts.untracked + counts.staged + counts.renamed + counts.deleted > 0;
}

function getTokenTotals(ctx: ExtensionContext): TokenTotals {
  const totals: TokenTotals = { input: 0, output: 0, cost: 0 };

  for (const entry of ctx.sessionManager.getBranch()) {
    if (entry.type !== "message") continue;
    const message = entry.message as {
      role?: string;
      usage?: { input?: number; output?: number; cost?: { total?: number } };
    };
    if (message.role !== "assistant") continue;

    totals.input += message.usage?.input ?? 0;
    totals.output += message.usage?.output ?? 0;
    totals.cost += message.usage?.cost?.total ?? 0;
  }

  return totals;
}

