function codexValueSegments(value: string): Array<{ text: string; fg: string; bold?: boolean }> {
  return value.split(/\s+/).map((token) => {
    const percent = Number(token.match(/^(\d{1,3})%$/)?.[1]);
    if (Number.isFinite(percent)) {
      return { text: token, fg: codexPercentColor(percent), bold: true };
    }
    return { text: token, fg: /^(5h|wk)$/iu.test(token) ? COLOR.dim : COLOR.soft };
  });
}

function codexPercentColor(percent: number): string {
  const clamped = Math.max(0, Math.min(100, percent));
  if (clamped <= 10) return COLOR.contextRed;
  if (clamped <= 20) return COLOR.contextLightRed;
  if (clamped <= 35) return COLOR.contextOrange;
  if (clamped <= 50) return COLOR.contextYellow;
  if (clamped <= 70) return COLOR.contextStrongGreen;
  if (clamped <= 90) return COLOR.contextGreen;
  return COLOR.contextLightGreen;
}

